/* Three presentation-only Realm map directions on the existing route via ?map=A|B|C.
   All variants consume the same live journey state and actions. No rule changes. */
const RealmMapStudy=(()=>{
    const titles={A:'A · Ember Atlas',B:'B · Guardian Gates',C:'C · Astral Compass'};
    let band=null,lastModal=null;
    const key=()=>new URLSearchParams(location.search).get('map');
    const enabled=()=>RealmProgression.enabled()&&Object.hasOwn(titles,key());
    const model=()=>RealmProgression.inspect();
    const pair=()=>({tier:state.modal.journeyTier??model().tier,realm:state.modal.journeyRealm??model().realm});
    const bounds=i=>({from:i?MageRealms.journey.bossNodes[i-1]+1:1,to:MageRealms.journey.bossNodes[i]});
    const currentBand=s=>Math.max(0,MageRealms.journey.bossNodes.findIndex(n=>n>=s.node));
    function bossName(r,i){return i===3?MageRealms.routes[r].boss.guardian:r===0?['The Ember Watcher','The Cinder Warden','The Ashen Knight'][i]:realms[r]+' '+['Watcher','Warden','Knight'][i];}
    const inspect=()=>({variant:key(),band,journey:model()});
    function basis(){const d=document.createElement('div');d.innerHTML=RealmProgression.view();return d;}
    function nodeHTML(base,n,extra='',style=''){const el=base.querySelector('[data-journey-node="'+n+'"]');const node=el.cloneNode(true);node.classList.add(...extra.split(' ').filter(Boolean));if(style)node.setAttribute('style',style);return node.outerHTML;}
    function atlas(base,s,tier,realm){
        const points=Array.from({length:25},(_,i)=>{const row=Math.floor(i/5),col=row%2?4-i%5:i%5;return{x:8.3+col*20.85+[-.15,.2,-.2,.15,0][i%5],y:10+row*20+(row>0&&row<4?[0,.1,-.15,.15,0][i%5]:0)};});
        const cleared=MageRealms.journey.cleared(s,tier,realm);
        return `<div class="map-atlas map-study-canvas realm-${realms[realm].toLowerCase()}"><div class="scenery map-terrain ${realm===1?'ice':''}" style="--realm-x:${({0:0,2:50,3:100})[realm]||0}%"></div><div class="map-atlas-shade"></div><svg class="map-geometry atlas-trail" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${points.slice(1).map((p,i)=>{const a=points[i];return `<path class="${i+2<=cleared?'done':''}" d="M${a.x} ${a.y} Q${(a.x+p.x)/2} ${a.y} ${p.x} ${p.y}"/>`;}).join('')}</svg>${points.map((p,i)=>nodeHTML(base,i+1,'atlas-marker',`left:${p.x}%;top:${p.y}%`)).join('')}</div>`;
    }
    function gates(base,s,tier,realm){const cleared=MageRealms.journey.cleared(s,tier,realm),same=tier===s.tier&&realm===s.realm;return `<div class="map-gates map-study-canvas">${MageRealms.journey.bossNodes.map((boss,i)=>{const b=bounds(i),active=same&&s.node>=b.from&&s.node<=b.to,done=cleared>=boss,ready=cleared===boss-1&&MageRealms.journey.canVisit(s,tier,realm);return `<button class="map-band-card ${active?'current':''} ${done?'complete':''} ${ready?'ready':''}" data-map-band="${i}" aria-label="${bossName(realm,i)}, nodes ${b.from} through ${b.to}${active?', farming here':done?', cleared':''}. Explore this path"><span class="gate-portrait">${sprite(i===3?'golem':['portal','workshop','mine'][i])}${done?'<i>✓</i>':''}</span><span class="gate-copy"><strong>${bossName(realm,i).replace(/^The /,'')}</strong><span class="band-track" aria-hidden="true">${Array.from({length:boss-b.from+1},(_,j)=>`<i class="${b.from+j<=cleared?'done':''} ${same&&b.from+j===s.node?'here':''} ${j===boss-b.from?'boss-pip':''}"></i>`).join('')}</span><small>${b.from}–${b.to} <span>${ready?'Boss ready':active?'Farming here':done?'Cleared':'Explore'}</span></small></span><span class="gate-count">${done?'✓':Math.max(0,Math.min(boss-b.from+1,cleared-b.from+1))+' / '+(boss-b.from+1)}<b aria-hidden="true">›</b></span></button>`;}).join('')}</div>`;}
    function compass(base,s,tier,realm){const cleared=MageRealms.journey.cleared(s,tier,realm),same=tier===s.tier&&realm===s.realm,node=same?s.node:MageRealms.journey.frontier(s,tier,realm),active=currentBand({...s,node});return `<div class="map-compass map-study-canvas"><div class="star-field"></div><svg class="map-geometry star-rings" viewBox="0 0 300 300" preserveAspectRatio="none" aria-hidden="true"><circle cx="150" cy="150" r="111"/><circle class="star-inner" cx="150" cy="150" r="78"/><circle class="star-progress" cx="150" cy="150" r="111" pathLength="100" stroke-dasharray="${cleared/25*100} 100" transform="rotate(-90 150 150)"/>${Array.from({length:25},(_,i)=>{const a=(i+1)/25*Math.PI*2-Math.PI/2;return `<path class="${i+1<=cleared?'done':''}" d="M${150+Math.cos(a)*122} ${150+Math.sin(a)*122} L${150+Math.cos(a)*128} ${150+Math.sin(a)*128}"/>`;}).join('')}</svg>${MageRealms.journey.bossNodes.map((n,i)=>{const a=n/25*Math.PI*2-Math.PI/2,done=cleared>=n,ready=cleared===n-1&&MageRealms.journey.canVisit(s,tier,realm);return `<button class="star-gate ${done?'complete':''} ${ready?'ready':''}" data-map-band="${i}" style="left:${50+Math.cos(a)*37}%;top:${50+Math.sin(a)*37}%" aria-label="${bossName(realm,i)}, boss node ${n}${done?', cleared':ready?', ready':''}. View path">${sprite('golem')}<b>${n}${done?' ✓':''}</b></button>`;}).join('')}<button class="star-portal" data-map-current="" data-map-band="${active}" aria-label="Node ${node} of 25. Open the current path">${sprite('portal')}<strong>${node}<small> / 25</small></strong><span>View path</span></button></div>`;}
    function focus(base,s,tier,realm){const b=bounds(band);return `<div class="map-focus map-study-canvas focus-${key()}"><div class="focus-heading"><button class="text-button" data-map-overview aria-label="Back to realm overview">←</button><div><strong>${bossName(realm,band)}</strong><span>Nodes ${b.from}–${b.to}</span></div></div><div class="focus-path" role="group" aria-label="Nodes ${b.from} through ${b.to}">${Array.from({length:b.to-b.from+1},(_,i)=>nodeHTML(base,b.from+i,'focus-marker')).join('')}</div><div class="focus-goal">${sprite('golem')}<span>Boss · ${b.to}</span></div></div>`;}
    function view(){if(state.modal!==lastModal){band=null;lastModal=state.modal;}const s=model(),{tier,realm}=pair(),base=basis(),heading=base.querySelector('.tier-map-heading').outerHTML,tabs=base.querySelector('.tier-realms').outerHTML,footer=base.querySelector('.journey-footer').outerHTML;if(tier===s.tier&&realm===s.realm)base.querySelector('.journey-position strong').textContent+=' · Node '+s.node;const content=band!==null?focus(base,s,tier,realm):key()==='A'?atlas(base,s,tier,realm):key()==='B'?gates(base,s,tier,realm):compass(base,s,tier,realm);const legend=band!==null||key()==='A'?base.querySelector('.journey-map-key').outerHTML:`<div class="journey-map-key"><span>25 nodes</span><span>${sprite('golem')} 4 bosses</span><span>${key()==='B'?'Choose a gate':'Tap a seal'}</span></div>`;return `<div class="tier-journey realm-map-study map-${key()}" data-map-layout="${key()}">${heading}${tabs}${base.querySelector('.journey-position').outerHTML}${content}${legend}${footer}</div>`;}
    function refreshAtlas(){const root=phone.querySelector('.realm-map-study');if(!root)return;const next=document.createElement('div');next.innerHTML=view();for(const old of root.querySelectorAll('button')){const attr=['data-journey-node','data-map-current','data-map-band','data-map-overview','data-journey-primary','data-journey-realm','data-journey-tier'].find(k=>old.hasAttribute(k));if(!attr)continue;const fresh=next.querySelector('['+attr+'="'+old.getAttribute(attr)+'"]');if(!fresh)continue;old.className=fresh.className;old.disabled=fresh.disabled;old.innerHTML=fresh.innerHTML;for(const k of ['aria-current','aria-label','aria-pressed', 'style']){if(fresh.hasAttribute(k))old.setAttribute(k,fresh.getAttribute(k));else old.removeAttribute(k);}}
        for(const selector of ['.map-geometry','.journey-position']){const old=root.querySelector(selector),fresh=next.querySelector(selector);if(old&&fresh)old.innerHTML=fresh.innerHTML;}
        const old=root.querySelector('.journey-footer>button'),fresh=next.querySelector('.journey-footer>button');if(old&&fresh){old.innerHTML=fresh.innerHTML;old.disabled=fresh.disabled;old.className=fresh.className;if(fresh.dataset.journeyPrimary)old.dataset.journeyPrimary=fresh.dataset.journeyPrimary;}
    }
    function change(delta){const keys=Object.keys(titles),u=new URL(location.href);u.searchParams.set('map',keys[(keys.indexOf(key())+delta+3)%3]);history.replaceState(null,'',u);band=null;if(state.modal?.type!=='map')state.modal={type:'map'};render(true);}
    function handle(el){if(el.dataset.journeyScenario){band=null;RealmProgression.scenario(el.dataset.journeyScenario);openModal({type:'map'});return true;}if(el.dataset.mapBand!==undefined){band=Number(el.dataset.mapBand);render(true);return true;}if(el.hasAttribute('data-map-overview')){band=null;render(true);return true;}if(el.dataset.mapChoice){const u=new URL(location.href);u.searchParams.set('map',el.dataset.mapChoice);history.replaceState(null,'',u);band=null;if(state.modal?.type!=='map')state.modal={type:'map'};render(true);return true;}if(el.dataset.journeyRealm!==undefined||el.dataset.journeyTier!==undefined||el.dataset.journeyScenario)band=null;return false;}
    function start(){if(!enabled())return;document.body.classList.add('map-comparison');document.querySelector('.prototype-switcher>span').textContent='REALM MAP';document.querySelector('#previous').setAttribute('aria-label','Föregående kartförslag');document.querySelector('#next').setAttribute('aria-label','Nästa kartförslag');document.querySelector('.prototype-switcher').setAttribute('aria-label','Jämför kartförslagen A, B och C');openModal({type:'map'});}
    return {enabled,inspect,view,refreshAtlas,change,handle,label:()=>titles[key()],start};
})();
